import net.minecraft.resources.ResourceLocation;
import java.util.UUID;

@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class WGServerTests {
    @GameTest(template="empty")
    public static void cloakInventoryRetainsAllSlotsAndNbt(GameTestHelper h){var cloak=new ItemStack(Content.CLOAKS.get("cloak_storage").get());var contents=NonNullList.withSize(27,ItemStack.EMPTY);var item=new ItemStack(Items.DIAMOND,37);item.getOrCreateTag().putString("Preserve","cloak27");contents.set(26,item);CloakItem.store(cloak,contents);var restored=ItemStack.of(cloak.save(new net.minecraft.nbt.CompoundTag()));h.assertTrue(CloakItem.contents(restored).get(26).getCount()==37&&CloakItem.contents(restored).get(26).getTag().getString("Preserve").equals("cloak27"),"27th slot and custom data survive save");h.assertTrue(!cloak.getItem().canFitInsideContainerItems(),"Storage cloak cannot recursively nest in bags");pass(h);}
    @GameTest(template="empty")
    public static void wolfCloakAndRavenRetainOriginalRules(GameTestHelper h){var player=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("086d23e8-dbd7-4308-840f-0b07a1b3e6ea"),"CloakTester"));var ctx=new top.theillusivec4.curios.api.SlotContext("cloak",player,0,false,true);var wolf=new ItemStack(Content.CLOAKS.get("cloak_wolf").get());wolf.getOrCreateTag().putInt("wolfPotion",3);((CloakItem)wolf.getItem()).curioTick(ctx,wolf);h.assertTrue(player.getEffect(net.minecraft.world.effect.MobEffects.DAMAGE_BOOST).getAmplifier()==3&&player.getEffect(net.minecraft.world.effect.MobEffects.DAMAGE_RESISTANCE).getDuration()==60,"Wolf activates all buffs for 60 ticks at saved damage tier");h.assertTrue(!wolf.getTag().contains("wolfPotion"),"Damage trigger consumed once");var raven=new ItemStack(Content.CLOAKS.get("cloak_raven").get());player.setOnGround(false);player.setShiftKeyDown(false);player.getAbilities().flying=false;player.setDeltaMovement(0,-1,0);player.fallDistance=18;((CloakItem)raven.getItem()).curioTick(ctx,raven);h.assertTrue(Math.abs(player.getDeltaMovement().y+.5)<.0001&&player.fallDistance==0,"Raven halves falling velocity and removes fall damage");raven.getOrCreateTag().putBoolean("noGlide",true);player.setDeltaMovement(0,-1,0);((CloakItem)raven.getItem()).curioTick(ctx,raven);h.assertTrue(player.getDeltaMovement().y==-1,"Raven toggle disables glide");pass(h);}
    @GameTest(template="empty")
    public static void accessoriesHaveUniqueSlotsAndModifiers(GameTestHelper h){var player=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("29b3e842-60ed-46e0-b493-a721b16e3f4e"),"GearTester"));var context=new top.theillusivec4.curios.api.SlotContext("shoulders",player,0,false,true);var knock=new ItemStack(Content.GEAR.get("shoulders_knockback").get());var item=(WGAccessories.Gear)knock.getItem();h.assertTrue(item.canEquip(context,knock),"Shoulder item accepts shoulder slot");h.assertTrue(!item.canEquip(new top.theillusivec4.curios.api.SlotContext("ring",player,0,false,true),knock),"Shoulder cannot exploit ring slots");var mods=item.getAttributeModifiers(context,UUID.randomUUID(),knock);h.assertTrue(mods.get(net.minecraft.world.entity.ai.attributes.Attributes.KNOCKBACK_RESISTANCE).iterator().next().getAmount()==.6,"Original 0.6 knockback resistance modifier");for(String research:new String[]{"CLOAK","CLOAK_SPECTRAL","CLOAK_STORAGE","CLOAK_WOLF","WGBAUBLES","CLOAKKAMA"})h.assertTrue(tc4revival.research.ResearchCatalogs.catalog().find("witchinggadgets:"+research).isPresent(),"Accessory research present "+research);for(String recipe:new String[]{"cloak_spectral","vambrace_haste","shoulders_doublejump","ring_sniper","ring_luck","lucky_coin"})h.assertTrue(h.getLevel().getRecipeManager().byKey(new ResourceLocation("witchinggadgets",recipe)).isPresent(),"Accessory recipe loaded "+recipe);pass(h);}
    @GameTest(template="empty")
    public static void etherealNetworkSplitsAndKeepsCamouflage(GameTestHelper h){var level=h.getLevel();var start=h.absolutePos(new BlockPos(1,2,2));for(int x=0;x<4;x++)level.setBlockAndUpdate(start.east(x),Content.ETHEREAL_WALL.get().defaultBlockState());level.setBlockAndUpdate(start.west(),Blocks.REDSTONE_BLOCK.defaultBlockState());var tile=(EtherealWall.Tile)level.getBlockEntity(start);EtherealWall.Tile.tick(level,start,tile.getBlockState(),tile);h.assertTrue(level.getBlockState(start.east(3)).getValue(EtherealWall.PASSABLE),"One signal opens entire connected wall");tile.setCamouflage(Blocks.OAK_LOG.defaultBlockState().setValue(net.minecraft.world.level.block.RotatedPillarBlock.AXIS,Direction.Axis.X));var nbt=tile.saveWithFullMetadata();tile.load(nbt);h.assertTrue(tile.camouflage.is(Blocks.OAK_LOG)&&tile.camouflage.getValue(net.minecraft.world.level.block.RotatedPillarBlock.AXIS)==Direction.Axis.X,"Camouflage retains block and orientation");level.setBlockAndUpdate(start.east(1),Blocks.AIR.defaultBlockState());var remote=(EtherealWall.Tile)level.getBlockEntity(start.east(3));EtherealWall.Tile.tick(level,remote.getBlockPos(),remote.getBlockState(),remote);h.assertTrue(!level.getBlockState(start.east(3)).getValue(EtherealWall.PASSABLE),"Disconnected wall stops inheriting old network power");pass(h);}
    @GameTest(template="empty")
    public static void saunaConsumesWaterAndFloodFillsRoom(GameTestHelper h){var l=h.getLevel();for(int x=1;x<=5;x++)for(int z=1;z<=5;z++)for(int y=0;y<=4;y++)l.setBlockAndUpdate(h.absolutePos(new BlockPos(x,y,z)),(x==1||x==5||z==1||z==5||y==0||y==4?Blocks.STONE:Blocks.AIR).defaultBlockState());var pos=h.absolutePos(new BlockPos(3,1,3));l.setBlockAndUpdate(pos,Content.SAUNA.get().defaultBlockState());var tile=(SaunaStove.Tile)l.getBlockEntity(pos);h.assertTrue(tile.tank.fill(new net.minecraftforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.LAVA,1000),net.minecraftforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE)==0,"Lava rejected");tile.tank.fill(new net.minecraftforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000),net.minecraftforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE);SaunaStove.Tile.tick(l,pos,tile.getBlockState(),tile);h.assertTrue(tile.fuel==1200&&tile.tank.isEmpty(),"One bucket buys 1200 ten-tick fuel units");for(int i=0;i<50;i++)tile.scan();h.assertTrue(tile.steamArea().contains(pos.above())&&!tile.steamArea().contains(pos.east(3)),"Steam reaches room and stops at walls");h.assertTrue(!tile.getCapability(net.minecraftforge.common.capabilities.ForgeCapabilities.FLUID_HANDLER,Direction.UP).isPresent(),"No fluid automation through stove top");var save=tile.saveWithFullMetadata();tile.load(save);h.assertTrue(tile.fuel==1200,"Fuel survives reload");pass(h);}
    @GameTest(template="empty")
    public static void cuttingAffinitiesAndVirtualOutputSurviveSave(GameTestHelper h){var pos=h.absolutePos(new BlockPos(1,2,1));h.getLevel().setBlockAndUpdate(pos,Content.CUTTING.get().defaultBlockState());var tile=(CuttingTable.Tile)h.getLevel().getBlockEntity(pos);tile.setItem(0,new ItemStack(Items.DIAMOND,2));for(int i=1;i<4;i++)tile.setItem(i,tc4revival.content.EssentiaPhialItem.filled(tc4revival.aspect.TCAspects.catalog().require("ordo")));h.assertTrue(!tile.getItem(4).isEmpty(),"Diamond and order phials produce a gem");h.assertTrue(net.minecraft.world.item.enchantment.EnchantmentHelper.getItemEnchantmentLevel(WGMagic.ENCHANTS.get("gemstone_potency").get(),tile.getItem(4))==3,"Point cut uses all three affinity inputs");tile.cut=1;tile.changed();h.assertTrue(net.minecraft.world.item.enchantment.EnchantmentHelper.getItemEnchantmentLevel(WGMagic.ENCHANTS.get("gemstone_potency").get(),tile.getItem(4))==2,"Oval trades one potency for reusability");var saved=tile.saveWithFullMetadata();h.assertTrue(saved.getList("Items",10).size()==4,"Preview never serialized as a fifth real stack");tile.load(saved);h.assertTrue(InfusedGem.cut(tile.getItem(4))==1&&!tile.accepts(tc4revival.content.EssentiaPhialItem.filled(tc4revival.aspect.TCAspects.catalog().require("ignis"))),"Cut survives reload and mixed aspects rejected");pass(h);}
    @GameTest(template="empty")
    public static void cuttingShiftClickConsumesOnlyProducedItems(GameTestHelper h){var pos=h.absolutePos(new BlockPos(1,2,1));h.getLevel().setBlockAndUpdate(pos,Content.CUTTING.get().defaultBlockState());var tile=(CuttingTable.Tile)h.getLevel().getBlockEntity(pos);var player=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("043d4dc9-e6c4-411f-8130-df5b8f217356"),"GemCutter"));player.getInventory().clearContent();player.setPos(pos.getX()+.5,pos.getY()+1,pos.getZ()+.5);tile.setItem(0,new ItemStack(Items.DIAMOND,4));var phial=tc4revival.content.EssentiaPhialItem.filled(tc4revival.aspect.TCAspects.catalog().require("ordo"));phial.setCount(2);tile.setItem(1,phial);var menu=new CuttingMenu(1,player.getInventory(),pos);menu.quickMoveStack(player,4);int count=player.getInventory().items.stream().filter(x->x.is(Content.INFUSED_GEM.get())).mapToInt(ItemStack::getCount).sum();h.assertTrue(count==2&&tile.getItem(0).getCount()==2&&tile.getItem(1).isEmpty()&&tile.getItem(4).isEmpty(),"Two phials produce precisely two gems and consume two diamonds");for(int i=0;i<36;i++)player.getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));tile.setItem(1,tc4revival.content.EssentiaPhialItem.filled(tc4revival.aspect.TCAspects.catalog().require("ordo")));menu.quickMoveStack(player,4);h.assertTrue(tile.getItem(0).getCount()==2&&tile.getItem(1).getCount()==1,"Full inventory cannot lose ingredients");pass(h);}
    @GameTest(template="empty")
    public static void infusedGemUseAndAversionUseOriginalRules(GameTestHelper h){var player=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("c11e202e-78be-4d24-804f-1c13acbe2b57"),"GemUser"));player.getInventory().clearContent();player.getInventory().selected=0;var gem=InfusedGem.create("aer",0);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,gem);gem.getItem().use(h.getLevel(),player,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertTrue(player.getEffect(net.minecraft.world.effect.MobEffects.JUMP).getAmplifier()==4,"Point air gem grants original jump V");h.assertTrue(gem.isEmpty()&&player.getInventory().items.stream().anyMatch(x->x.is(Content.MATERIALS.get("gemstone_dust").get())),"Point use returns dust and consumes exactly one gem");var brittle=InfusedGem.create("ignis",1);brittle.enchant(WGMagic.ENCHANTS.get("gemstone_brittle").get(),3);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,brittle);brittle.getItem().use(h.getLevel(),player,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertTrue(brittle.isEmpty(),"Brittleness III shatters deterministically before applying effect");var oval=InfusedGem.create("terra",1);oval.setDamageValue(32);h.assertTrue(oval.getMaxDamage()==32&&oval.getMaxStackSize()==1&&oval.getItem().isBarVisible(oval),"Reusable oval has 32-point charge and visible empty bar");pass(h);}
    @GameTest(template="empty")
    public static void accessoryEnchantmentAcceptsUndamageableGear(GameTestHelper h){var recipe=(AccessoryEnchantRecipe)h.getLevel().getRecipeManager().byKey(new ResourceLocation("witchinggadgets","enchant_invisible_gear")).orElseThrow();var cloak=new ItemStack(Content.CLOAKS.get("cloak_standard").get());h.assertTrue(!cloak.isDamageableItem()&&recipe.acceptsCenter(cloak),"Original isItemTool cloak can receive invisible gear despite no durability");cloak.enchant(WGMagic.ENCHANTS.get("invisible_gear").get(),2);h.assertTrue(!recipe.acceptsCenter(cloak),"Max level cannot be infused again");var unveiling=(AccessoryEnchantRecipe)h.getLevel().getRecipeManager().byKey(new ResourceLocation("witchinggadgets","enchant_unveiling")).orElseThrow();h.assertTrue(!unveiling.acceptsCenter(new ItemStack(Content.GEAR.get("ring_luck").get())),"Unveiling remains restricted to revealing head gear");for(String key:new String[]{"GEMCUTTING","ENCH_INVISIBLEGEAR","ENCH_UNVEILING","ENCH_STEALTH","ENCH_BACKSTAB","ENCH_RIDEPROTECT","WGPOTIONS"})h.assertTrue(tc4revival.research.ResearchCatalogs.catalog().find("witchinggadgets:"+key).isPresent(),"Research registered "+key);pass(h);}
    private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
    @GameTest(template="empty")
    public static void spinningConsumesDistinctSlotsOnce(GameTestHelper h){var pos=h.absolutePos(new BlockPos(1,2,1));h.getLevel().setBlockAndUpdate(pos,Content.SPINNING_WHEEL.get().defaultBlockState());var tile=(SpinningWheel.Tile)h.getLevel().getBlockEntity(pos);for(int i=0;i<4;i++)tile.setItem(i,new ItemStack(Items.STRING,2));for(int i=0;i<121;i++)SpinningWheel.Tile.tick(h.getLevel(),pos,tile.getBlockState(),tile);h.assertTrue(tile.getItem(5).is(Content.MATERIALS.get("thread_simple").get())&&tile.getItem(5).getCount()==2,"4 string produces 2 threads at 121 ticks");for(int i=0;i<4;i++)h.assertTrue(tile.getItem(i).getCount()==1,"Each distinct slot consumed once");tile.setItem(4,new ItemStack(Items.DIRT));for(int i=0;i<121;i++)SpinningWheel.Tile.tick(h.getLevel(),pos,tile.getBlockState(),tile);h.assertTrue(tile.getItem(5).getCount()==2,"Extra unmatched input blocks recipe");pass(h);}
    @GameTest(template="empty")
    public static void spinningFullOutputDoesNotConsume(GameTestHelper h){var pos=h.absolutePos(new BlockPos(1,2,1));h.getLevel().setBlockAndUpdate(pos,Content.SPINNING_WHEEL.get().defaultBlockState());var tile=(SpinningWheel.Tile)h.getLevel().getBlockEntity(pos);for(int i=0;i<4;i++)tile.setItem(i,new ItemStack(Items.STRING,3));tile.setItem(5,new ItemStack(Content.MATERIALS.get("thread_simple").get(),64));for(int i=0;i<200;i++)SpinningWheel.Tile.tick(h.getLevel(),pos,tile.getBlockState(),tile);h.assertTrue(tile.getItem(0).getCount()==3&&tile.progress==0,"No consumption or progress with full output");pass(h);}
    @GameTest(template="empty")
    public static void bagsPersistNbtAndEnforceOwnership(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("432a4bb7-fdc2-45fd-981b-c6d9f0e42200"),"BagOwnerTester"));p.getAbilities().instabuild=false;var bag=new ItemStack(Content.BAG.get());bag.getOrCreateTag().putUUID("Owner",UUID.fromString("2982c784-d6ba-422e-b548-0d68e8de7d8a"));h.assertTrue(!BagItem.permitted(bag,p),"Non-owner rejected");bag.getOrCreateTag().putBoolean("Unlocked",true);h.assertTrue(BagItem.permitted(bag,p),"Unlocked bag permits sharing");var list=NonNullList.withSize(18,ItemStack.EMPTY);var diamond=new ItemStack(Items.DIAMOND,11);diamond.getOrCreateTag().putString("Preserve","yes");list.set(17,diamond);BagItem.store(bag,list);var copy=ItemStack.of(bag.save(new net.minecraft.nbt.CompoundTag()));h.assertTrue(BagItem.contents(copy).get(17).getCount()==11&&BagItem.contents(copy).get(17).getTag().getString("Preserve").equals("yes"),"Slot 17 item count and custom NBT survive save");pass(h);}
    @GameTest(template="empty")
    public static void voidFilterDoesNotDuplicateHeldItems(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("f07b3b9b-052f-4817-a5a3-30df4b177a74"),"VoidBagTester"));p.getInventory().selected=0;p.getInventory().setItem(0,new ItemStack(Content.VOID_BAG.get()));var menu=new BagMenu(1,p.getInventory(),false);menu.setCarried(new ItemStack(Items.DIAMOND,32));menu.clicked(0,0,ClickType.PICKUP,p);h.assertTrue(menu.contents.getItem(0).getCount()==1&&menu.getCarried().getCount()==32,"Filter copies one phantom without consuming carried stack");menu.clicked(0,1,ClickType.PICKUP,p);h.assertTrue(menu.contents.getItem(0).isEmpty()&&menu.getCarried().getCount()==32,"Right click removes phantom without giving items");menu.clicked(45,0,ClickType.PICKUP,p);h.assertTrue(p.getInventory().getItem(0).is(Content.VOID_BAG.get()),"Bound held bag cannot be removed");pass(h);}
    @GameTest(template="empty")
    public static void extruderHonorsInventoryAndRedstone(GameTestHelper h){var pos=h.absolutePos(new BlockPos(2,2,2));h.getLevel().setBlockAndUpdate(pos,Content.EXTRUDER.get().defaultBlockState().setValue(StoneDevices.Extruder.FACING,Direction.EAST));h.getLevel().setBlockAndUpdate(pos.east(),Blocks.CHEST.defaultBlockState());var tile=(StoneDevices.ExtruderTile)h.getLevel().getBlockEntity(pos);var chest=(ChestBlockEntity)h.getLevel().getBlockEntity(pos.east());for(int i=0;i<40;i++)StoneDevices.ExtruderTile.tick(h.getLevel(),pos,tile.getBlockState(),tile);h.assertTrue(chest.getItem(0).is(Items.COBBLESTONE)&&chest.getItem(0).getCount()==1,"40 ticks inserts one cobble into facing inventory");h.getLevel().setBlockAndUpdate(pos.above(),Blocks.REDSTONE_BLOCK.defaultBlockState());for(int i=0;i<80;i++)StoneDevices.ExtruderTile.tick(h.getLevel(),pos,tile.getBlockState(),tile);h.assertTrue(chest.getItem(0).getCount()==1,"Redstone pauses production");h.getLevel().setBlockAndUpdate(pos.above(),Blocks.AIR.defaultBlockState());for(int i=0;i<chest.getContainerSize();i++)chest.setItem(i,new ItemStack(Items.COBBLESTONE,64));h.assertTrue(!tile.canWork(),"Full adjacent inventory prevents progress");pass(h);}
    @GameTest(template="empty")
    public static void ageingChangesOnlyNearbyAgeableMobs(GameTestHelper h){var pos=h.absolutePos(new BlockPos(2,2,2));h.getLevel().setBlockAndUpdate(pos,Content.AGEING_STONE.get().defaultBlockState());var tile=(StoneDevices.AgeingTile)h.getLevel().getBlockEntity(pos);var baby=EntityType.COW.create(h.getLevel());baby.moveTo(pos.getX()+.5,pos.getY()+1,pos.getZ()+.5);baby.setAge(-100);h.getLevel().addFreshEntity(baby);StoneDevices.AgeingTile.tick(h.getLevel(),pos,tile.getBlockState(),tile);h.assertTrue(baby.getAge()==-99,"Adds one extra growing tick");baby.setAge(200);StoneDevices.AgeingTile.tick(h.getLevel(),pos,tile.getBlockState(),tile);h.assertTrue(baby.getAge()==199,"Also reduces breeding cooldown");baby.discard();pass(h);}
    @GameTest(template="empty")
    public static void robeDiscountAndTextileResearch(GameTestHelper h){h.assertTrue(((AdvancedRobe)Content.ROBE_CHEST.get()).getVisDiscount(ItemStack.EMPTY,null,null)==5,"Robe chest discount 5%");h.assertTrue(((AdvancedRobe)Content.ROBE_LEGS.get()).getVisDiscount(ItemStack.EMPTY,null,null)==4,"Robe legs discount 4%");for(var key:new String[]{"SPINNINGWHEEL","BAGOFTRICKS","ADVANCEDROBES","STONEEXTRUDER","AGEINGSTONE"})h.assertTrue(tc4revival.research.ResearchCatalogs.catalog().find("witchinggadgets:"+key).isPresent(),"Research registered "+key);for(var id:new String[]{"thread_simple","cloth_bewitched","advanced_robe_chest","void_bag","stone_extruder","ageing_stone"})h.assertTrue(h.getLevel().getRecipeManager().byKey(new ResourceLocation("witchinggadgets",id)).isPresent(),"Recipe loaded "+id);pass(h);}
}
